// Concatenate the exam-prep and voice-tutor migrations into one paste file.
//
// The Supabase SQL editor takes one paste, and these files have to run
// in a specific order that fails SILENTLY when shuffled -- 01 creates the
// unique index that 03 to 06 insert against, and an insert against the wrong
// index drops rows through "on conflict do nothing" without a word. Handing
// someone seven files and an instruction to be careful is how that happens.
//
// Generated rather than hand-maintained, so the bundle cannot drift from the
// migrations. Run: node scripts/build-sql-bundle.mjs

import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { join } from "node:path";

const MIGRATIONS = join(process.cwd(), "supabase", "migrations");
const OUT_DIR = join(process.cwd(), "docs", "sql");
const OUT = join(OUT_DIR, "apply-2026-09-06.sql");

/** Order is the whole point of this file. See the header it writes. */
const FILES = [
  "20260906_01_diagnostic_question_identity_fix.sql",
  "20260906_02_exam_definitions_expansion.sql",
  "20260906_03_act_question_bank.sql",
  "20260906_04_nclex_rn_question_bank.sql",
  "20260906_05_mcat_question_bank.sql",
  "20260906_06_gre_question_bank.sql",
  "20260906_07_voice_topic_tutoring.sql",
  // Added after the 09-06 set had already been applied to a live database.
  // Kept in the same bundle so a fresh database gets everything in one paste;
  // it is ON CONFLICT DO NOTHING like every other seed, so a database that
  // already ran the earlier files just picks up the new questions.
  "20260908_01_mcat_bank_topup.sql",
  // Corrections to content already inserted above. They run last because
  // they rewrite rows the inserts create, and an UPDATE before its INSERT
  // silently does nothing.
  "20260908_02_american_spelling.sql",
  "20260908_03_question_quality.sql",
];

const DOLLAR = "$" + "$";
const RULE = "-- " + "=".repeat(70);

const HEADER = `-- AceDecks -- exam prep and the voice tutor, in one paste.
--
-- The eight exam and voice migrations, concatenated in the order they must
-- run. Generated by scripts/build-sql-bundle.mjs from supabase/migrations/ --
-- edit those, not this.
--
-- Paste the whole file into the Supabase SQL editor and run it once. It is
-- safe to run more than once: every table and index is guarded with IF NOT
-- EXISTS, every insert is ON CONFLICT DO NOTHING, and the one UPDATE is
-- idempotent.
--
-- The ordering is load-bearing and fails SILENTLY if you shuffle it. File 01
-- creates the unique index that files 03 to 06 insert against, and an insert
-- against the old index drops rows through ON CONFLICT DO NOTHING without a
-- word -- which is exactly how a third of the SAT bank went missing. File 02
-- widens the question_type constraint the select-all questions need, and
-- gives each exam the configuration without which the engine cannot read its
-- own bank. Top to bottom, or not at all.
--
-- Every statement below was parsed with PostgreSQL's own grammar
-- (libpg_query) before this file was generated.

${RULE}
-- PREFLIGHT
${RULE}
--
-- Stops with one readable message instead of a cascade of failures if an
-- earlier migration was never applied. Not hypothetical:
-- 20260715_diagnostics_and_study_plans.sql shipped with an undoubled
-- apostrophe inside a string literal, so it could never have run against
-- Postgres. If this preflight stops you, that is why -- the file has now
-- been fixed, so apply it and the diagnostic migrations after it, then come
-- back here.

do ${DOLLAR}
begin
  if to_regclass('public.exam_definitions') is null then
    raise exception 'AceDecks: table public.exam_definitions is missing.'
      using hint = 'Apply supabase/migrations/20260715_diagnostics_and_study_plans.sql (just fixed), then the diagnostic migrations up to 20260731, then re-run this bundle.';
  end if;

  if to_regclass('public.diagnostic_questions') is null then
    raise exception 'AceDecks: table public.diagnostic_questions is missing.'
      using hint = 'Apply supabase/migrations/20260715_diagnostics_and_study_plans.sql first, then re-run this bundle.';
  end if;

  if to_regclass('public.voice_sessions') is null then
    raise exception 'AceDecks: table public.voice_sessions is missing.'
      using hint = 'Apply supabase/migrations/20260902_voice_tutor_sessions.sql first, then re-run this bundle.';
  end if;
end
${DOLLAR};
`;

const FOOTER = `

${RULE}
-- WHAT YOU SHOULD SEE AFTERWARDS
${RULE}
--
-- Run this to confirm. Five rows, all 'available', with these counts.
-- Anything lower means a bank did not land.
--
--   select e.slug, e.status, count(q.id) as published
--   from public.exam_definitions e
--   left join public.diagnostic_questions q
--     on q.exam_id = e.id and q.status = 'published'
--   group by e.slug, e.status
--   order by published desc;
--
--   digital-sat  available  98
--   act          available  60
--   nclex-rn     available  57
--   mcat         available  43
--   gre          available  20
--
-- The other four rows (psat-nmsqt, lsat, ap-exams, nclex-pn) stay
-- 'coming_soon' with zero questions. That is correct: there is no bank
-- behind them, and /exams says so rather than offering practice.
`;

let out = HEADER;
for (const file of FILES) {
  const sql = readFileSync(join(MIGRATIONS, file), "utf8").replace(/\r\n/g, "\n");
  out += `\n\n${RULE}\n-- FILE: ${file}\n${RULE}\n\n${sql.trim()}\n`;
}
out += FOOTER;

mkdirSync(OUT_DIR, { recursive: true });
writeFileSync(OUT, out, "utf8");

console.log(`wrote ${OUT}`);
console.log(`${out.split("\n").length} lines, ${FILES.length} migrations`);
